from copy import copy
from openpyxl import load_workbook
from openpyxl.utils import get_column_letter

path = '/root/output/result.xlsx'
wb = load_workbook(path, data_only=False)
if 'Task' not in wb.sheetnames or 'Data' not in wb.sheetnames:
    raise RuntimeError(f"Required sheets missing. Found: {wb.sheetnames}")
ws = wb['Task']

# Capture all pre-edit values to verify only target cells change.
before = {}
for sheet in wb.worksheets:
    for row in sheet.iter_rows():
        for cell in row:
            before[(sheet.title, cell.coordinate)] = cell.value

# Step 1: two-dimensional lookup by series code in Task column D and year in Task row 10.
# Data layout from inspection: series codes in Data!D21:D38; year headers in Data!H4:L4;
# year values in Data!H21:L38.
lookup_rows = list(range(12, 18)) + list(range(19, 25)) + list(range(26, 32))
for r in lookup_rows:
    for c in range(8, 13):  # H:L
        col = get_column_letter(c)
        ws.cell(r, c).value = f'=INDEX(Data!$H$21:$L$38,MATCH($D{r},Data!$D$21:$D$38,0),MATCH({col}$10,Data!$H$4:$L$4,0))'

# Step 2: Net container flow for each port: (Inbound - Outbound) / Capacity * 100.
# Task rows 12:17 inbound, 19:24 outbound, 26:31 capacity, 35:40 net flow.
for out_r in range(35, 41):
    port_index = out_r - 35
    inbound_r = 12 + port_index
    outbound_r = 19 + port_index
    capacity_r = 26 + port_index
    for c in range(8, 13):
        col = get_column_letter(c)
        ws.cell(out_r, c).value = f'=({col}{inbound_r}-{col}{outbound_r})/{col}{capacity_r}*100'

# Step 2 statistics, matching labels inspected in E42:E47.
stat_formulas = {
    42: 'MIN',
    43: 'MAX',
    44: 'MEDIAN',
    45: 'AVERAGE',
}
for c in range(8, 13):
    col = get_column_letter(c)
    for r, fn in stat_formulas.items():
        ws.cell(r, c).value = f'={fn}({col}35:{col}40)'
    ws.cell(46, c).value = f'=PERCENTILE.INC({col}35:{col}40,0.25)'
    ws.cell(47, c).value = f'=PERCENTILE.INC({col}35:{col}40,0.75)'

# Step 3 weighted mean using capacity weights.
for c in range(8, 13):
    col = get_column_letter(c)
    ws.cell(50, c).value = f'=SUMPRODUCT({col}35:{col}40,{col}26:{col}31)/SUM({col}26:{col}31)'

# Verify only intended target cells changed.
targets = set()
for r in lookup_rows + list(range(35, 41)) + list(range(42, 48)) + [50]:
    for c in range(8, 13):
        targets.add(('Task', f'{get_column_letter(c)}{r}'))

changed_outside = []
for sheet in wb.worksheets:
    for row in sheet.iter_rows():
        for cell in row:
            key = (sheet.title, cell.coordinate)
            if before.get(key) != cell.value and key not in targets:
                changed_outside.append((key, before.get(key), cell.value))
if changed_outside:
    raise RuntimeError(f'Unexpected changes outside target ranges: {changed_outside[:10]}')

missing = []
for _, coord in targets:
    v = ws[coord].value
    if not (isinstance(v, str) and v.startswith('=')):
        missing.append((coord, v))
if missing:
    raise RuntimeError(f'Target cells missing formulas: {missing[:10]}')

wb.save(path)
print(f'Saved formulas to {path}')
print(f'Target formula cells written: {len(targets)}')
print('Changed outside target ranges: 0')
print('Sample formulas before reopen:')
for coord in ['H12','I12','H19','H26','H35','H42','H46','H50','L50']:
    print(coord, ws[coord].value)
